package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.os.*;import android.provider.Settings;import android.text.InputType;import android.widget.*;import java.util.*;

/** Persistent parent-granted foreground-use allowance. No daily reset or screen contents. */
final class ParentalTimer {
 private static Context app;private static final Handler handler=new Handler(Looper.getMainLooper());private static String internal="";private static boolean queued;private static final ForegroundAllowance clock=new ForegroundAllowance(new ForegroundAllowance.Store(){public long read(String id){return app==null?-1:remaining(app,id);}public void write(String id,long left){if(app!=null)prefs(app).edit().putLong("budget:"+id,left).apply();}});
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("tvmorph-parental-time",0);}
 static long remaining(Context c,String id){return prefs(c).getLong("budget:"+id,-1);}
 static boolean any(Context c){for(String k:prefs(c).getAll().keySet())if(k.startsWith("budget:"))return true;return false;}
 private static String t(Context c,String ar,String en){return FamilyText.t(c,ar,en);}
 private static boolean builtIn(String id){return id.equals("local.tvmorph.tv.kids")||id.equals("local.tvmorph.tv.play")||id.equals("local.tvmorph.tv.radio");}
 static void clear(Context c){prefs(c).edit().clear().apply();clock.focus("",SystemClock.elapsedRealtime());internal="";HomeOverrideService.refresh();}
 static void set(Context c,String id,int minutes){app=c.getApplicationContext();settle();SharedPreferences.Editor e=prefs(c).edit();if(minutes<=0)e.remove("budget:"+id);else e.putLong("budget:"+id,minutes*60000L);e.apply();HomeOverrideService.refresh();schedule();}
 static void enter(Context c,String id){app=c.getApplicationContext();settle();internal=id;clock.focus(id,SystemClock.elapsedRealtime());if(remaining(app,id)==0){TimeUpActivity.open(app,id);clock.focus("",SystemClock.elapsedRealtime());internal="";}else schedule();}
 static void leave(String id){if(internal.equals(id)){settle();internal="";clock.focus("",SystemClock.elapsedRealtime());}}
 static void window(Context c,String pkg){if(pkg==null||pkg.isEmpty()||pkg.equals("null"))return;app=c.getApplicationContext();if(pkg.equals(c.getPackageName())&&!internal.isEmpty())return;settle();clock.focus(pkg,SystemClock.elapsedRealtime());schedule();}
 static void sleep(){settle();clock.focus("",SystemClock.elapsedRealtime());internal="";}
 static String current(){return clock.current();}
 static org.json.JSONObject status(Context c)throws Exception{settle();String id=clock.current(),name=id;try{name=c.getPackageManager().getApplicationLabel(c.getPackageManager().getApplicationInfo(id,0)).toString();}catch(Exception ignored){}return new org.json.JSONObject().put("id",id).put("name",name).put("remainingMs",remaining(c,id)).put("serviceEnabled",HomeOverrideService.granted(c)).put("serviceRunning",HomeOverrideService.running());}
 static boolean stop(Context c,String id){app=c.getApplicationContext();settle();prefs(c).edit().putLong("budget:"+id,0).apply();HomeOverrideService.refresh();return TimeUpActivity.open(c,id);}
 private static void settle(){clock.settle(SystemClock.elapsedRealtime());}
 private static void schedule(){if(queued||app==null||clock.current().isEmpty()||remaining(app,clock.current())<0)return;queued=true;handler.postDelayed(()->{queued=false;settle();if(app!=null&&!clock.current().isEmpty()&&remaining(app,clock.current())==0){String id=clock.current();clock.focus("",SystemClock.elapsedRealtime());internal="";TimeUpActivity.open(app,id);}else schedule();},1000);}
 static boolean allow(Activity a,String id){long left=remaining(a,id);if(left==0){TimeUpActivity.open(a,id);return false;}if(left>0&&!builtIn(id)&&!HomeOverrideService.granted(a)){permission(a);return false;}return true;}
 private static void permission(Activity a){new AlertDialog.Builder(a).setTitle(t(a,"الرقابة الأبوية","Parental controls")).setMessage(t(a,"توقيت التطبيقات الخارجية يحتاج خدمة التنقل في Morph TV. فعّلها يدويًا من إعدادات التلفزيون ← تسهيلات الاستخدام. الخدمة تتابع اسم التطبيق الظاهر فقط لحساب وقت استخدامه، ولا تقرأ محتوى الشاشة. الوقت رصيد محفوظ لا يتجدد يوميًا تلقائيًا.","Time limits for external apps require the Morph TV navigation service. Enable it manually in TV Settings → Accessibility. The service observes the foreground app package name to count use, without reading screen contents. Time is a saved allowance, not an automatic daily reset.")).setPositiveButton(t(a,"فتح تسهيلات الاستخدام","Open Accessibility settings"),(d,w)->{try{a.startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}catch(Exception ignored){}}).setNegativeButton(t(a,"رجوع","Back"),null).show();}
 static void configure(Activity a,String id){PlusAccess.require(a,()->configureVerified(a,id));}
 private static void configureVerified(Activity a,String id){String[] options={t(a,"بدون حد زمني","No time limit"),t(a,"١٥ دقيقة","15 minutes"),t(a,"٣٠ دقيقة","30 minutes"),t(a,"٦٠ دقيقة","60 minutes"),t(a,"دقائق مخصّصة","Custom minutes")};new AlertDialog.Builder(a).setTitle(t(a,"وقت التطبيقات المسموح","App time allowances")).setItems(options,(d,w)->{if(w<4){int[] values={0,15,30,60};set(a,id,values[w]);if(values[w]>0&&!builtIn(id)&&!HomeOverrideService.granted(a))permission(a);}else{EditText input=new EditText(a);input.setSingleLine(true);input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setHint(t(a,"دقائق من ١ إلى ١٤٤٠","Minutes (1–1440)"));AlertDialog custom=new AlertDialog.Builder(a).setTitle(options[4]).setView(SystemTextInput.wrap(a,input,true)).setPositiveButton(t(a,"حفظ","Save"),null).setNegativeButton(t(a,"إلغاء","Cancel"),null).create();custom.setOnShowListener(x->custom.getButton(-1).setOnClickListener(v->{int minutes=0;try{minutes=Integer.parseInt(input.getText().toString());}catch(Exception ignored){}if(minutes<1||minutes>1440){input.setError(t(a,"اكتب رقمًا من ١ إلى ١٤٤٠.","Enter a number from 1 to 1440."));return;}set(a,id,minutes);custom.dismiss();if(!builtIn(id)&&!HomeOverrideService.granted(a))permission(a);}));custom.show();}}).setNegativeButton(t(a,"رجوع","Back"),null).show();}
}
